import * as vscode from "vscode";
import type { GoalContract, ProjectDescriptor } from "../model";
import type { Store } from "../store";

class ProjectItem extends vscode.TreeItem {
  constructor(readonly project: ProjectDescriptor) {
    super(project.name, vscode.TreeItemCollapsibleState.Collapsed);
    this.description = project.buildProfile?.kind ?? "no build profile";
    this.tooltip = `${project.rootPath}\nbranch: ${project.defaultBranch}`;
    this.contextValue = "jarvisProject";
    this.iconPath = new vscode.ThemeIcon("repo");
    this.id = `project:${project.id}`;
  }
}

class GoalItem extends vscode.TreeItem {
  constructor(readonly goal: GoalContract) {
    super(goal.title, vscode.TreeItemCollapsibleState.None);
    this.description = goal.status;
    this.contextValue = "jarvisGoal";
    this.iconPath = new vscode.ThemeIcon("target");
    this.id = `goal:${goal.id}`;
  }
}

export class ProjectsView implements vscode.TreeDataProvider<vscode.TreeItem> {
  private readonly emitter = new vscode.EventEmitter<void>();
  readonly onDidChangeTreeData = this.emitter.event;

  constructor(private readonly store: Store) {
    store.onDidChange(() => this.emitter.fire());
  }

  getTreeItem(element: vscode.TreeItem): vscode.TreeItem {
    return element;
  }

  async getChildren(element?: vscode.TreeItem): Promise<vscode.TreeItem[]> {
    if (!this.store.snapshot.online) {
      return [offline()];
    }
    if (!element) {
      const projects = this.store.snapshot.projects;
      return projects.length > 0
        ? projects.map((p) => new ProjectItem(p))
        : [hint("No projects — register this workspace", "jarvis.registerWorkspace")];
    }
    if (element instanceof ProjectItem) {
      try {
        const goals = await this.store.client.goals(element.project.id);
        return goals.length > 0 ? goals.map((g) => new GoalItem(g)) : [hint("No goals yet")];
      } catch {
        return [offline()];
      }
    }
    return [];
  }
}

function offline(): vscode.TreeItem {
  const item = new vscode.TreeItem("Daemon offline", vscode.TreeItemCollapsibleState.None);
  item.iconPath = new vscode.ThemeIcon("debug-disconnect");
  item.description = "start jarvisd";
  return item;
}

function hint(label: string, command?: string): vscode.TreeItem {
  const item = new vscode.TreeItem(label, vscode.TreeItemCollapsibleState.None);
  item.iconPath = new vscode.ThemeIcon("info");
  if (command) item.command = { command, title: label };
  return item;
}
