import * as vscode from "vscode";
import { getCommandBridgeUrl } from "./config";
import { DaemonClient, DaemonUnreachableError } from "./daemonClient";
import type { DaemonLauncher } from "./daemonLauncher";
import type { GoalContract, ProjectDescriptor } from "./model";
import { renderEvidenceManifest } from "./presentation";
import type { Store } from "./store";
import type { ApprovalItem } from "./views/approvalsView";
import type { WorkflowItem } from "./views/workflowsView";

/** Registers every jarvis.* command. Returns disposables for the context. */
export function registerCommands(
  client: DaemonClient,
  store: Store,
  showOutput: () => void,
  launcher: DaemonLauncher,
): vscode.Disposable[] {
  const reg = vscode.commands.registerCommand;

  const withDaemon = async (fn: () => Promise<void>): Promise<void> => {
    try {
      await fn();
      await store.refresh();
    } catch (err) {
      if (err instanceof DaemonUnreachableError) {
        void vscode.window
          .showErrorMessage("Jarvis daemon is not reachable.", "Start daemon")
          .then((choice) => {
            if (choice === "Start daemon") void launcher.start();
          });
      } else {
        void vscode.window.showErrorMessage(`Jarvis: ${err instanceof Error ? err.message : String(err)}`);
      }
    }
  };

  return [
    reg("jarvis.refresh", () => withDaemon(async () => {})),

    reg("jarvis.registerWorkspace", () =>
      withDaemon(async () => {
        const folder = vscode.workspace.workspaceFolders?.[0];
        if (!folder) {
          void vscode.window.showWarningMessage("Open a folder to register it as a Jarvis project.");
          return;
        }
        const project = await client.registerProject(folder.uri.fsPath);
        void vscode.window.showInformationMessage(
          `Registered ${project.name} (${project.buildProfile?.kind ?? "no build profile detected"}).`,
        );
      }),
    ),

    reg("jarvis.engage", () =>
      withDaemon(async () => {
        const project = await pickProject(store);
        if (!project) return;
        const directive = await vscode.window.showInputBox({
          title: "Jarvis · Engage a Directive",
          prompt: `Goal for ${project.name}`,
          placeHolder: "e.g. Add a /health endpoint returning service status",
          ignoreFocusOut: true,
        });
        if (!directive?.trim()) return;

        const agent = await pickAgent(store);
        const goal = await client.createGoal({
          project: project.id,
          title: directive.length > 80 ? `${directive.slice(0, 77)}...` : directive,
          objective: directive,
          agent: agent ?? undefined,
        });
        const workflow = await client.runGoal(goal.id);
        showOutput();
        void vscode.window.showInformationMessage(`Engaged · workflow ${workflow.id.slice(-8)} running.`);
      }),
    ),

    reg("jarvis.runGoal", (item?: { goal?: GoalContract }) =>
      withDaemon(async () => {
        const goal = item?.goal;
        if (!goal) return;
        const workflow = await client.runGoal(goal.id);
        showOutput();
        void vscode.window.showInformationMessage(`Running · workflow ${workflow.id.slice(-8)}.`);
      }),
    ),

    reg("jarvis.cancelWorkflow", (item?: WorkflowItem) =>
      withDaemon(async () => {
        const workflow = item?.workflow ?? (await pickActiveWorkflow(store));
        if (!workflow) return;
        await client.cancelWorkflow(workflow.id);
        void vscode.window.showInformationMessage(`Cancelled workflow ${workflow.id.slice(-8)}.`);
      }),
    ),

    reg("jarvis.approve", (item?: ApprovalItem) =>
      withDaemon(async () => {
        const approval = item?.approval ?? (await pickApproval(store));
        if (!approval) return;
        await client.resolveApproval(approval.id, true, actorId());
        void vscode.window.showInformationMessage("Approved. The jarvis/* branch is kept; merge when ready.");
      }),
    ),

    reg("jarvis.deny", (item?: ApprovalItem) =>
      withDaemon(async () => {
        const approval = item?.approval ?? (await pickApproval(store));
        if (!approval) return;
        await client.resolveApproval(approval.id, false, actorId());
        void vscode.window.showInformationMessage("Denied. Worktree and branch removed; evidence retained.");
      }),
    ),

    reg("jarvis.showDiff", (item?: WorkflowItem | ApprovalItem) => showDiff(client, store, item)),

    reg("jarvis.showEvidence", (item?: WorkflowItem | ApprovalItem) =>
      withDaemon(async () => {
        const workflowId = workflowIdOf(item) ?? (await pickActiveWorkflow(store, true))?.id;
        if (!workflowId) return;
        const manifest = await client.evidence(workflowId);
        if (!manifest) {
          void vscode.window.showInformationMessage("No evidence published for this workflow yet.");
          return;
        }
        const doc = await vscode.workspace.openTextDocument({
          content: renderEvidenceManifest(manifest),
          language: "markdown",
        });
        await vscode.window.showTextDocument(doc, { preview: true });
      }),
    ),

    reg("jarvis.openCommandBridge", async () => {
      await vscode.env.openExternal(vscode.Uri.parse(getCommandBridgeUrl()));
    }),

    reg("jarvis.startDaemon", () => launcher.start()),
  ];
}

/** Workflow id carried by a tree item, when the command came from the tree. */
function workflowIdOf(item?: WorkflowItem | ApprovalItem): string | undefined {
  if (item && "workflow" in item) return item.workflow.id;
  if (item && "approval" in item) return item.approval.workflowId;
  return undefined;
}

async function showDiff(
  client: DaemonClient,
  store: Store,
  item?: WorkflowItem | ApprovalItem,
): Promise<void> {
  const workflowId = workflowIdOf(item) ?? (await pickActiveWorkflow(store, true))?.id;
  if (!workflowId) return;

  try {
    const patch = await client.diff(workflowId);
    if (!patch) {
      void vscode.window.showInformationMessage("No diff available for this workflow yet.");
      return;
    }
    // Native diff-language document — VS Code renders the patch with SCM coloring.
    const doc = await vscode.workspace.openTextDocument({ content: patch, language: "diff" });
    await vscode.window.showTextDocument(doc, { preview: true });
  } catch (err) {
    void vscode.window.showErrorMessage(`Jarvis: ${err instanceof Error ? err.message : String(err)}`);
  }
}

async function pickProject(store: Store): Promise<ProjectDescriptor | undefined> {
  const projects = store.snapshot.projects;
  if (projects.length === 0) {
    void vscode.window.showWarningMessage("No projects registered. Run 'Jarvis: Register This Workspace'.");
    return undefined;
  }
  if (projects.length === 1) return projects[0];
  const pick = await vscode.window.showQuickPick(
    projects.map((p) => ({ label: p.name, description: p.rootPath, project: p })),
    { title: "Target project" },
  );
  return pick?.project;
}

async function pickAgent(store: Store): Promise<string | null> {
  const available = store.snapshot.agents.filter((a) => a.available);
  if (available.length <= 1) return null;
  const pick = await vscode.window.showQuickPick(
    [
      { label: "Auto (router decides)", id: null as string | null },
      ...available.map((a) => ({ label: a.id, id: a.id as string | null })),
    ],
    { title: "Routing (optional)" },
  );
  return pick?.id ?? null;
}

async function pickActiveWorkflow(store: Store, includeDone = false) {
  const candidates = includeDone
    ? store.snapshot.workflows
    : store.snapshot.workflows.filter((w) => !["completed", "discarded", "failed", "cancelled"].includes(w.state));
  if (candidates.length === 0) return undefined;
  if (candidates.length === 1) return candidates[0];
  const pick = await vscode.window.showQuickPick(
    candidates.map((w) => ({ label: `wf ${w.id.slice(-8)}`, description: w.state, workflow: w })),
    { title: "Workflow" },
  );
  return pick?.workflow;
}

async function pickApproval(store: Store) {
  const approvals = store.snapshot.approvals;
  if (approvals.length === 0) {
    void vscode.window.showInformationMessage("No pending approvals.");
    return undefined;
  }
  if (approvals.length === 1) return approvals[0];
  const pick = await vscode.window.showQuickPick(
    approvals.map((a) => ({ label: a.summary.split(" — ")[0], description: a.risk, approval: a })),
    { title: "Approval" },
  );
  return pick?.approval;
}

function actorId(): string {
  return process.env.USERNAME ?? process.env.USER ?? "forge";
}
