import * as vscode from "vscode";
import { DaemonClient } from "./daemonClient";
import type {
  AgentInfo,
  ApprovalRequest,
  DaemonStatus,
  ProjectDescriptor,
  WorkflowSummary,
} from "./model";

/** Snapshot of daemon state shared by the views + status bar. */
export interface Snapshot {
  online: boolean;
  /** A daemon launch is in flight (jarvis.startDaemon waiting on the health probe). */
  connecting: boolean;
  status: DaemonStatus | null;
  projects: ProjectDescriptor[];
  workflows: WorkflowSummary[];
  approvals: ApprovalRequest[];
  agents: AgentInfo[];
}

const EMPTY: Snapshot = {
  online: false,
  connecting: false,
  status: null,
  projects: [],
  workflows: [],
  approvals: [],
  agents: [],
};

/** Central polled state. Views subscribe to onDidChange and re-read `snapshot`. */
export class Store {
  private readonly emitter = new vscode.EventEmitter<Snapshot>();
  readonly onDidChange = this.emitter.event;
  private current: Snapshot = EMPTY;

  constructor(readonly client: DaemonClient) {}

  get snapshot(): Snapshot {
    return this.current;
  }

  async refresh(): Promise<void> {
    try {
      const [status, projects, workflows, approvals, agents] = await Promise.all([
        this.client.status(),
        this.client.projects(),
        this.client.workflows(),
        this.client.approvals(),
        this.client.agents(),
      ]);
      this.current = { online: true, connecting: false, status, projects, workflows, approvals, agents };
    } catch {
      this.current = { ...EMPTY, online: false, connecting: this.current.connecting };
    }
    this.emitter.fire(this.current);
  }

  /** Marks a daemon launch as in flight so the status bar can show it. */
  setConnecting(connecting: boolean): void {
    if (this.current.connecting === connecting) return;
    this.current = { ...this.current, connecting };
    this.emitter.fire(this.current);
  }

  dispose(): void {
    this.emitter.dispose();
  }
}
