import * as vscode from "vscode";
import type { ApprovalRequest } from "../model";
import type { Store } from "../store";

export class ApprovalItem extends vscode.TreeItem {
  constructor(readonly approval: ApprovalRequest) {
    super(approval.summary.split(" — ")[0] ?? approval.summary, vscode.TreeItemCollapsibleState.None);
    this.description = approval.risk;
    this.tooltip = approval.summary;
    this.contextValue = "jarvisApproval";
    this.iconPath = new vscode.ThemeIcon(
      "clock",
      new vscode.ThemeColor("notificationsWarningIcon.foreground"),
    );
    this.id = `approval:${approval.id}`;
  }
}

export class ApprovalsView implements vscode.TreeDataProvider<vscode.TreeItem> {
  private readonly emitter = new vscode.EventEmitter<void>();
  readonly onDidChangeTreeData = this.emitter.event;

  constructor(private readonly store: Store) {
    store.onDidChange(() => this.emitter.fire());
  }

  getTreeItem(element: vscode.TreeItem): vscode.TreeItem {
    return element;
  }

  getChildren(): vscode.TreeItem[] {
    const snap = this.store.snapshot;
    if (!snap.online) {
      const item = new vscode.TreeItem("Daemon offline", vscode.TreeItemCollapsibleState.None);
      item.iconPath = new vscode.ThemeIcon("debug-disconnect");
      return [item];
    }
    if (snap.approvals.length === 0) {
      const item = new vscode.TreeItem("Nothing waiting on you", vscode.TreeItemCollapsibleState.None);
      item.iconPath = new vscode.ThemeIcon("check-all");
      return [item];
    }
    return snap.approvals.map((a) => new ApprovalItem(a));
  }
}
