import * as vscode from "vscode";
import { registerCommands } from "./commands";
import { getDaemonUrl } from "./config";
import { DaemonClient } from "./daemonClient";
import { DaemonLauncher } from "./daemonLauncher";
import { PollService } from "./pollService";
import { StatusBar } from "./statusBar";
import { Store } from "./store";
import { ApprovalsView } from "./views/approvalsView";
import { ProjectsView } from "./views/projectsView";
import { WorkflowsView } from "./views/workflowsView";

export function activate(context: vscode.ExtensionContext): void {
  const client = new DaemonClient(getDaemonUrl());
  const store = new Store(client);
  const poll = new PollService(store, client);
  const launcher = new DaemonLauncher(store, (line) => poll.log(line));

  context.subscriptions.push(
    store,
    poll,
    launcher,
    new StatusBar(store),
    vscode.window.registerTreeDataProvider("jarvis.projects", new ProjectsView(store)),
    vscode.window.registerTreeDataProvider("jarvis.workflows", new WorkflowsView(store)),
    vscode.window.registerTreeDataProvider("jarvis.approvals", new ApprovalsView(store)),
    ...registerCommands(client, store, () => poll.show(), launcher),
  );

  poll.start();
  // Forge is inert without jarvisd — probe once and offer to start it.
  void launcher.offerStartIfOffline();
}

export function deactivate(): void {
  // context.subscriptions are disposed by VS Code.
}
