import * as vscode from "vscode";

export const DEFAULT_DAEMON_URL = "http://localhost:5178";
export const DEFAULT_COMMAND_BRIDGE_URL = "http://localhost:1420";

/** Base URL of the local daemon; read lazily so settings changes take effect. */
export function getDaemonUrl(): string {
  const value = vscode.workspace.getConfiguration("jarvis").get<string>("daemonUrl", DEFAULT_DAEMON_URL);
  return value?.trim() ? value.trim() : DEFAULT_DAEMON_URL;
}

export function getCommandBridgeUrl(): string {
  return (
    vscode.workspace
      .getConfiguration("jarvis")
      .get<string>("commandBridgeUrl", DEFAULT_COMMAND_BRIDGE_URL) ?? DEFAULT_COMMAND_BRIDGE_URL
  );
}

/** Raw `jarvis.daemonLaunch` value — validated by `daemonLaunch.validateLaunchSpec`. */
export function getDaemonLaunchSetting(): unknown {
  return vscode.workspace.getConfiguration("jarvis").get<unknown>("daemonLaunch") ?? null;
}

/** Opens the launch setting in the Settings editor. */
export async function openLaunchSetting(): Promise<void> {
  await vscode.commands.executeCommand("workbench.action.openSettings", "jarvis.daemonLaunch");
}
