// Daemon reachability probe + payload parsing. No `vscode` import — pure and
// unit-tested. The daemon (jarvisd) exposes `GET /healthz` → {"status":"ok"};
// older builds only had `GET /api/v1/status`, so a 404 falls back to that.

export const HEALTH_PATH = "/healthz";
export const STATUS_PATH = "/api/v1/status";

/** Default per-probe timeout; the daemon is loopback, so it answers fast or not at all. */
export const DEFAULT_PROBE_TIMEOUT_MS = 2000;
/** Re-probe cadence while waiting for a freshly launched daemon. */
export const DEFAULT_PROBE_INTERVAL_MS = 2000;
/** How long we wait for a launched daemon to answer before giving up. */
export const DEFAULT_STARTUP_TIMEOUT_MS = 60_000;

export interface DaemonHealth {
  /** True when the daemon answered and did not report an unhealthy status. */
  readonly online: boolean;
  /** Daemon version when the payload carried one (`/api/v1/status`). */
  readonly version?: string;
  /** Human-readable reason/annotation — never shown as an error on its own. */
  readonly detail?: string;
}

/** Minimal slice of `Response` the probe needs, so tests can inject a fake. */
export interface HealthResponse {
  readonly ok: boolean;
  readonly status: number;
  text(): Promise<string>;
}

/** Minimal slice of `fetch`; global `fetch` is assignable to it. */
export type HealthFetch = (
  url: string,
  init: { signal?: AbortSignal },
) => Promise<HealthResponse>;

export interface ProbeOptions {
  readonly fetch?: HealthFetch;
  readonly signal?: AbortSignal;
  readonly timeoutMs?: number;
}

/** Joins a configured base URL with a daemon path, tolerating a trailing slash. */
export function healthUrl(baseUrl: string, path: string = HEALTH_PATH): string {
  return `${baseUrl.trim().replace(/\/+$/, "")}${path}`;
}

/**
 * Interprets a health/status response. A 2xx answer means the daemon is up
 * unless it explicitly reports a non-ok status field.
 */
export function parseHealthPayload(status: number, body: string): DaemonHealth {
  if (status < 200 || status >= 300) {
    return { online: false, detail: `HTTP ${status}` };
  }

  const trimmed = body.trim();
  if (trimmed.length === 0) return { online: true };

  let payload: unknown;
  try {
    payload = JSON.parse(trimmed);
  } catch {
    return { online: true, detail: "non-JSON health payload" };
  }

  if (payload === null || typeof payload !== "object" || Array.isArray(payload)) {
    return { online: true, detail: "unrecognized health payload" };
  }

  const record = payload as Record<string, unknown>;
  const reported = typeof record["status"] === "string" ? String(record["status"]) : null;
  if (reported !== null && !["ok", "healthy", "up"].includes(reported.toLowerCase())) {
    return { online: false, detail: `daemon reports status "${reported}"` };
  }

  const version = typeof record["version"] === "string" ? String(record["version"]) : undefined;
  return version === undefined ? { online: true } : { online: true, version };
}

/** One probe of the daemon. Never throws — an unreachable daemon is `online: false`. */
export async function probeDaemonHealth(
  baseUrl: string,
  options: ProbeOptions = {},
): Promise<DaemonHealth> {
  const doFetch = options.fetch ?? (globalThis.fetch as unknown as HealthFetch);
  const signal = options.signal ?? timeoutSignal(options.timeoutMs ?? DEFAULT_PROBE_TIMEOUT_MS);

  const primary = await requestHealth(doFetch, healthUrl(baseUrl, HEALTH_PATH), signal);
  if ("error" in primary) return { online: false, detail: primary.error };
  if (primary.status !== 404) return parseHealthPayload(primary.status, primary.body);

  // Older daemon without /healthz — the status endpoint proves liveness.
  const fallback = await requestHealth(doFetch, healthUrl(baseUrl, STATUS_PATH), signal);
  if ("error" in fallback) return { online: false, detail: fallback.error };
  return parseHealthPayload(fallback.status, fallback.body);
}

export interface WaitForDaemonOptions {
  readonly probe: () => Promise<DaemonHealth>;
  readonly sleep?: (ms: number) => Promise<void>;
  readonly now?: () => number;
  readonly intervalMs?: number;
  readonly timeoutMs?: number;
  readonly isCancelled?: () => boolean;
  readonly onAttempt?: (attempt: number, health: DaemonHealth) => void;
}

export interface WaitForDaemonResult extends DaemonHealth {
  readonly attempts: number;
  readonly timedOut: boolean;
  readonly cancelled: boolean;
}

/**
 * Re-probes until the daemon answers, the deadline passes, or the caller
 * cancels. Timers are injected so this stays deterministic in tests.
 */
export async function waitForDaemon(options: WaitForDaemonOptions): Promise<WaitForDaemonResult> {
  const sleep = options.sleep ?? realSleep;
  const now = options.now ?? (() => Date.now());
  const intervalMs = options.intervalMs ?? DEFAULT_PROBE_INTERVAL_MS;
  const timeoutMs = options.timeoutMs ?? DEFAULT_STARTUP_TIMEOUT_MS;

  const startedAt = now();
  let attempts = 0;

  for (;;) {
    attempts += 1;
    const health = await options.probe();
    options.onAttempt?.(attempts, health);
    if (health.online) {
      return { ...health, attempts, timedOut: false, cancelled: false };
    }
    if (options.isCancelled?.() === true) {
      return { ...health, attempts, timedOut: false, cancelled: true };
    }
    if (now() - startedAt >= timeoutMs) {
      return { ...health, attempts, timedOut: true, cancelled: false };
    }
    await sleep(intervalMs);
  }
}

async function requestHealth(
  doFetch: HealthFetch,
  url: string,
  signal: AbortSignal | undefined,
): Promise<{ status: number; body: string } | { error: string }> {
  try {
    const response = await doFetch(url, { signal });
    const body = await response.text().catch(() => "");
    return { status: response.status, body };
  } catch (cause) {
    return { error: cause instanceof Error ? cause.message : String(cause) };
  }
}

function timeoutSignal(ms: number): AbortSignal | undefined {
  const factory = AbortSignal as unknown as { timeout?: (ms: number) => AbortSignal };
  return typeof factory.timeout === "function" ? factory.timeout(ms) : undefined;
}

function realSleep(ms: number): Promise<void> {
  return new Promise((resolve) => setTimeout(resolve, ms));
}
