// Resolution + validation of how to start the local daemon (jarvisd). No
// `vscode` import — pure and unit-tested; the caller feeds it the configured
// setting, the open workspace folders, and a file-exists probe.
//
// Security: the resolved spec is spawned as an argv vector
// (`createTerminal({ shellPath, shellArgs })`) — it is never concatenated into
// a shell string. Validation still rejects shell metacharacters and control
// characters so a hand-edited setting cannot smuggle one in if the launch path
// ever changes.

/** Executable + argument vector used to start the daemon. */
export interface DaemonLaunchSpec {
  readonly command: string;
  readonly args: string[];
  readonly cwd?: string;
}

export type LaunchSource =
  /** `jarvis.daemonLaunch` setting. */
  | "configured"
  /** Detected `src/Jarvis.Host/Jarvis.Host.csproj` in an open workspace folder. */
  | "workspace"
  /** Speculative `jarvisd` on PATH — may not exist; the startup probe decides. */
  | "path";

export type LaunchResolution =
  | { readonly kind: LaunchSource; readonly spec: DaemonLaunchSpec }
  | { readonly kind: "invalid"; readonly reason: string };

export interface ResolveLaunchInput {
  /** Raw `jarvis.daemonLaunch` value (unvalidated user JSON). */
  readonly configured?: unknown;
  /** Absolute paths of the open workspace folders, in order. */
  readonly workspaceFolders?: readonly string[];
  /** Injected file-exists probe (fs.existsSync in the extension host). */
  readonly exists?: (path: string) => boolean;
}

export type ValidationResult =
  | { readonly ok: true; readonly spec: DaemonLaunchSpec }
  | { readonly ok: false; readonly reason: string };

/** Relative location of the daemon project inside a Jarvis checkout. */
export const HOST_PROJECT_SEGMENTS = ["src", "Jarvis.Host", "Jarvis.Host.csproj"] as const;

/** Command assumed to be on PATH when no checkout is open. */
export const DEFAULT_DAEMON_COMMAND = "jarvisd";

// A bare executable name: no separators, no metacharacters, no leading dash.
const BARE_COMMAND = /^[A-Za-z0-9_][A-Za-z0-9._+-]*$/;
// Absolute path: drive-letter, UNC, or POSIX root.
const ABSOLUTE_PATH = /^(?:[A-Za-z]:[\\/]|\\\\[^\\/]|\/)/;
// Characters that only mean something to a shell — never needed in an argv exec.
const SHELL_METACHARACTERS = /[&|;<>$`(){}\[\]!*?"'\s]/;
// Control characters are never legitimate in an argument vector.
const CONTROL_CHARACTERS = /[\u0000-\u001f\u007f]/;

/** Validates raw setting JSON into a launch spec. */
export function validateLaunchSpec(raw: unknown): ValidationResult {
  if (raw === null || raw === undefined) {
    return { ok: false, reason: "no launch spec configured" };
  }
  if (typeof raw !== "object" || Array.isArray(raw)) {
    return { ok: false, reason: "jarvis.daemonLaunch must be an object" };
  }

  const record = raw as Record<string, unknown>;
  const command = record["command"];
  if (typeof command !== "string" || command.trim().length === 0) {
    return { ok: false, reason: "jarvis.daemonLaunch.command must be a non-empty string" };
  }
  const trimmedCommand = command.trim();
  if (SHELL_METACHARACTERS.test(trimmedCommand) || CONTROL_CHARACTERS.test(trimmedCommand)) {
    return {
      ok: false,
      reason: "jarvis.daemonLaunch.command must not contain shell metacharacters or spaces",
    };
  }
  if (!BARE_COMMAND.test(trimmedCommand) && !ABSOLUTE_PATH.test(trimmedCommand)) {
    return {
      ok: false,
      reason: "jarvis.daemonLaunch.command must be a bare executable name or an absolute path",
    };
  }

  const rawArgs = record["args"];
  let args: string[] = [];
  if (rawArgs !== undefined && rawArgs !== null) {
    if (!Array.isArray(rawArgs)) {
      return { ok: false, reason: "jarvis.daemonLaunch.args must be an array of strings" };
    }
    if (!rawArgs.every((a): a is string => typeof a === "string")) {
      return { ok: false, reason: "jarvis.daemonLaunch.args must contain strings only" };
    }
    if (rawArgs.some((a) => CONTROL_CHARACTERS.test(a))) {
      return { ok: false, reason: "jarvis.daemonLaunch.args must not contain control characters" };
    }
    args = [...rawArgs];
  }

  const rawCwd = record["cwd"];
  if (rawCwd !== undefined && rawCwd !== null) {
    if (typeof rawCwd !== "string" || rawCwd.trim().length === 0) {
      return { ok: false, reason: "jarvis.daemonLaunch.cwd must be a non-empty string" };
    }
    if (CONTROL_CHARACTERS.test(rawCwd)) {
      return { ok: false, reason: "jarvis.daemonLaunch.cwd must not contain control characters" };
    }
    return { ok: true, spec: { command: trimmedCommand, args, cwd: rawCwd } };
  }

  return { ok: true, spec: { command: trimmedCommand, args } };
}

/**
 * Resolution order:
 *   (a) the `jarvis.daemonLaunch` setting, when present and valid;
 *   (b) a workspace folder containing `src/Jarvis.Host/Jarvis.Host.csproj`
 *       → `dotnet run --project <that csproj>` with that folder as cwd;
 *   (c) `jarvisd`, assumed on PATH — speculative, the startup probe decides.
 * A present-but-invalid setting is an error rather than a silent fallback.
 */
export function resolveLaunchSpec(input: ResolveLaunchInput = {}): LaunchResolution {
  if (input.configured !== undefined && input.configured !== null) {
    const validated = validateLaunchSpec(input.configured);
    return validated.ok
      ? { kind: "configured", spec: validated.spec }
      : { kind: "invalid", reason: validated.reason };
  }

  const exists = input.exists;
  if (exists) {
    for (const folder of input.workspaceFolders ?? []) {
      if (typeof folder !== "string" || folder.length === 0) continue;
      const project = joinPath(folder, ...HOST_PROJECT_SEGMENTS);
      if (exists(project)) {
        return {
          kind: "workspace",
          spec: { command: "dotnet", args: ["run", "--project", project], cwd: folder },
        };
      }
    }
  }

  return { kind: "path", spec: { command: DEFAULT_DAEMON_COMMAND, args: [] } };
}

/** True when the spec is a guess that may simply not exist on this machine. */
export function isSpeculative(resolution: LaunchResolution): boolean {
  return resolution.kind === "path";
}

/** Display-only rendering of a spec — never executed as a shell string. */
export function formatLaunchCommand(spec: DaemonLaunchSpec): string {
  return [spec.command, ...spec.args].map(quoteForDisplay).join(" ");
}

/** Joins path segments using the separator style of the base path. */
export function joinPath(base: string, ...segments: string[]): string {
  const separator = base.includes("\\") && !base.includes("/") ? "\\" : "/";
  const trimmed = base.replace(/[\\/]+$/, "");
  return [trimmed, ...segments].join(separator);
}

function quoteForDisplay(token: string): string {
  return /\s/.test(token) ? `"${token}"` : token;
}
