// Pure presentation helpers — no `vscode` import, fully unit-tested. The
// vscode-facing providers map these to ThemeIcon/TreeItem.

import {
  TERMINAL_STATES,
  type EventEnvelope,
  type EvidenceManifest,
  type WorkflowSummary,
} from "./model";

/** Ordered stages of the workflow pipeline (matches the engine + Command Bridge). */
export const PIPELINE_STAGES = [
  "planned",
  "isolating",
  "planning",
  "executing",
  "verifying",
  "reviewing",
  "awaitingApproval",
] as const;

/** VS Code ThemeIcon id + optional ThemeColor id for a workflow state. */
export function workflowIcon(state: string): { icon: string; color?: string } {
  switch (state) {
    case "completed":
      return { icon: "pass-filled", color: "testing.iconPassed" };
    case "awaitingApproval":
      return { icon: "clock", color: "notificationsWarningIcon.foreground" };
    case "failed":
      return { icon: "error", color: "testing.iconFailed" };
    case "discarded":
    case "cancelled":
      return { icon: "circle-slash", color: "descriptionForeground" };
    default:
      return { icon: "sync~spin", color: "charts.blue" };
  }
}

/** Human label for a workflow state. */
export function workflowStateLabel(state: string): string {
  const words: Record<string, string> = {
    awaitingApproval: "Awaiting approval",
  };
  if (words[state]) return words[state];
  return state.charAt(0).toUpperCase() + state.slice(1);
}

/** 0..100 progress of a workflow through the pipeline. */
export function pipelineProgress(state: string): number {
  if (state === "completed") return 100;
  if (TERMINAL_STATES.has(state)) return 0;
  const idx = PIPELINE_STAGES.indexOf(state as (typeof PIPELINE_STAGES)[number]);
  if (idx < 0) return 0;
  return Math.round((idx / (PIPELINE_STAGES.length - 1)) * 100);
}

/** A short workflow description line for the tree item. */
export function workflowDescription(w: WorkflowSummary): string {
  const parts: string[] = [workflowStateLabel(w.state)];
  if (!TERMINAL_STATES.has(w.state)) {
    parts[0] = `${parts[0]} · ${pipelineProgress(w.state)}%`;
  }
  if (w.branchName) parts.push(w.branchName.replace(/^jarvis\//, ""));
  if (w.failureReason && (w.state === "failed" || w.state === "discarded")) {
    parts.push(truncate(w.failureReason, 60));
  }
  return parts.join(" · ");
}

/** One-line human summary for an event, for the output channel / activity feed. */
export function describeEvent(e: EventEnvelope): string {
  const data = e.data ?? {};
  const s = (k: string): string | null => (typeof data[k] === "string" ? String(data[k]) : null);
  const wf = e.correlationId?.slice(-8) ?? "";
  switch (e.eventType) {
    case "GoalCreated.v1":
      return `Goal created`;
    case "WorkflowStarted.v1":
      return `[${wf}] workflow engaged`;
    case "WorkspaceIsolated.v1":
      return `[${wf}] worktree isolated · network deny-default`;
    case "AgentSelected.v1":
      return `[${wf}] router → ${s("agentId")} (${s("role")?.toLowerCase() ?? "role"}) · ${s("rationale") ?? ""}`;
    case "PlanCreated.v1":
      return `[${wf}] implementation plan sealed`;
    case "AgentSessionCompleted.v1":
      return `[${wf}] agent session complete`;
    case "EvidencePublished.v1":
      return `[${wf}] evidence bundle published`;
    case "VerificationCompleted.v1":
      return `[${wf}] verification green → review`;
    case "ReviewCompleted.v1":
      return `[${wf}] review complete · approval requested`;
    case "ReviewRepairRequested.v1":
      return `[${wf}] repair round engaged`;
    case "PolicyDecisionMade.v1":
      return `[${wf}] sentinel decision recorded`;
    case "WorkflowCompleted.v1":
      return `[${wf}] ✓ complete · branch preserved`;
    case "WorkflowDiscarded.v1":
      return `[${wf}] ✕ discarded · worktree destroyed`;
    case "WorkflowFailed.v1":
      return `[${wf}] workflow failed`;
    case "WorkflowCancelled.v1":
      return `[${wf}] workflow cancelled`;
    default:
      return `[${wf}] ${e.eventType.replace(/\.v1$/, "")}`;
  }
}

/**
 * Renders an evidence manifest as Markdown for the editor. Wire-deserialized
 * collections can arrive `null` (contract types deserialize through the
 * constructor path), so every list is normalized before use.
 */
export function renderEvidenceManifest(manifest: EvidenceManifest): string {
  const items = manifest.items ?? [];
  const criteria = manifest.acceptanceCriteria ?? [];
  const lines: string[] = [
    `# Evidence · workflow ${manifest.workflowId}`,
    "",
    `- Manifest: \`${manifest.id}\``,
    `- Published: ${manifest.createdAt}`,
  ];
  if (manifest.manifestHash) lines.push(`- Manifest hash: \`${manifest.manifestHash}\``);

  lines.push("", `## Items (${items.length})`, "");
  if (items.length === 0) {
    lines.push("_No evidence items._");
  } else {
    for (const item of items) {
      lines.push(`- **${item.kind}** · ${outcomeMark(item.outcome)} ${item.title}`);
      if (item.summary) lines.push(`  - ${item.summary}`);
      if (item.artifact) {
        const size = item.artifact.sizeBytes === undefined ? "" : ` · ${item.artifact.sizeBytes} bytes`;
        lines.push(`  - artifact \`${item.artifact.sha256.slice(0, 12)}\`${size}`);
      }
    }
  }

  lines.push("", `## Acceptance criteria (${criteria.length})`, "");
  if (criteria.length === 0) {
    lines.push("_No acceptance criteria recorded._");
  } else {
    for (const criterion of criteria) {
      lines.push(`- ${outcomeMark(criterion.status)} ${criterion.criterion}`);
      if (criterion.note) lines.push(`  - ${criterion.note}`);
    }
  }

  return `${lines.join("\n")}\n`;
}

function outcomeMark(outcome: string): string {
  switch (outcome.toLowerCase()) {
    case "passed":
      return "✓";
    case "failed":
      return "✕";
    default:
      return "•";
  }
}

export function formatTimestamp(iso: string): string {
  const d = new Date(iso);
  const pad = (n: number) => String(n).padStart(2, "0");
  return `${pad(d.getHours())}:${pad(d.getMinutes())}:${pad(d.getSeconds())}`;
}

export function truncate(text: string, max: number): string {
  return text.length <= max ? text : `${text.slice(0, max - 1)}…`;
}
