import * as vscode from "vscode";
import type { DaemonClient } from "./daemonClient";
import { describeEvent, formatTimestamp } from "./presentation";
import type { Store } from "./store";

/**
 * Drives the extension's live state: a periodic snapshot refresh plus the
 * daemon's resumable long-poll event feed, which both refreshes views and
 * writes a human-readable line to the "Jarvis Forge" output channel.
 */
export class PollService implements vscode.Disposable {
  private readonly output: vscode.OutputChannel;
  private timer: ReturnType<typeof setInterval> | undefined;
  private abort: AbortController | undefined;
  private cursor = 0;
  private stopped = false;

  constructor(
    private readonly store: Store,
    private readonly client: DaemonClient,
  ) {
    this.output = vscode.window.createOutputChannel("Jarvis Forge");
  }

  start(): void {
    void this.store.refresh();
    this.timer = setInterval(() => void this.store.refresh(), 4000);
    void this.pumpEvents();
  }

  private async pumpEvents(): Promise<void> {
    while (!this.stopped) {
      this.abort = new AbortController();
      try {
        const batch = await this.client.events(this.cursor, 25, this.abort.signal);
        if (batch.length > 0) {
          this.cursor = Math.max(this.cursor, ...batch.map((e) => e.sequence));
          for (const event of batch) {
            this.output.appendLine(`${formatTimestamp(event.occurredAt)}  ${describeEvent(event)}`);
          }
          void this.store.refresh();
        }
      } catch {
        // daemon down or restarting — back off, then resume from the same cursor
        await delay(3000);
      }
    }
  }

  show(): void {
    this.output.show(true);
  }

  /** Writes a timestamped extension-side line (daemon launch, probes) to the channel. */
  log(message: string): void {
    this.output.appendLine(`${formatTimestamp(new Date().toISOString())}  ${message}`);
  }

  dispose(): void {
    this.stopped = true;
    if (this.timer) clearInterval(this.timer);
    this.abort?.abort();
    this.output.dispose();
  }
}

function delay(ms: number): Promise<void> {
  return new Promise((resolve) => setTimeout(resolve, ms));
}
